const { spawn } = require("child_process");
const http = require("http");
const p = spawn("/workspace/run-server", ["--data-dir", "/tmp/sbx/sig", "--port", "18085"], { stdio: ["ignore", "ignore", "ignore"] });
const t0 = Date.now();
const probe = () => http.get("http://127.0.0.1:18085/healthz", r => {
  console.log("healthz", r.statusCode, "after", Date.now() - t0, "ms");
  const t1 = Date.now(); p.kill("SIGINT");
  p.on("exit", (code, sig) => console.log("wrapper exit", code, sig, "after", Date.now() - t1, "ms"));
}).on("error", () => setTimeout(probe, 300));
probe();
EOF
